/* CSS PART 1 OF 3 */

/* Josh Brooks Construction — Design System */
:root {
  color-scheme: light;
  --ink: #202b32;
  --ink-soft: #52616a;
  --navy: #172b38;
  --navy-deep: #10212c;
  --blue: #315d70;
  --blue-hover: #24495b;
  --copper: #c17b4b;
  --copper-light: #e4b38c;
  --paper: #f8f7f3;
  --white: #ffffff;
  --surface: #efeee8;
  --line: #deded7;
  --muted: #78848a;

  --font-heading: "Arial", "Helvetica Neue", sans-serif;
  --font-body: "Inter", "Segoe UI", sans-serif;

  --container: 1180px;
  --header-height: 82px;
  --radius: 5px;
  --shadow: 0 18px 55px rgba(16, 33, 44, 0.13);
  --transition: 180ms ease;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  color: inherit;
}

::selection {
  color: var(--white);
  background: var(--blue);
}

:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Shared typography */
h1,
h2,
h3,
h4,
p {
  margin-top: 0;
}

h1,
h2,
h3,
h4 {
  color: var(--navy);
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  font-size: clamp(2.8rem, 5.7vw, 5.15rem);
}

h2 {
  font-size: clamp(2rem, 3.8vw, 3.35rem);
}

h3 {
  font-size: 1.35rem;
}

p {
  color: var(--ink-soft);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
  color: var(--copper);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 2px;
  background: currentColor;
  content: "";
}

.lead {
  max-width: 610px;
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.8;
}

.container {
  width: min(var(--container), calc(100% - 64px));
  margin-inline: auto;
}

.section {
  padding-block: 108px;
}

.section-heading {
  max-width: 720px;
  margin-bottom: 48px;
}

.section-heading h2 {
  margin-bottom: 18px;
}

.section-heading p {
  max-width: 600px;
  margin-bottom: 0;
  font-size: 1.05rem;
}

/* Header and navigation */
.site-header {
  position: relative;
  z-index: 20;
  width: 100%;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 43, 50, 0.09);
}

.header-inner {
  display: flex;
  min-height: var(--header-height);
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 13px;
  color: var(--navy);
}

.brand img {
  width: 54px;
  height: 54px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-name {
  font-family: var(--font-heading);
  font-size: 0.98rem;
  font-weight: 900;
  letter-spacing: -0.035em;
}

.brand-caption {
  margin-top: 5px;
  color: var(--muted);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.site-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(16px, 2.5vw, 32px);
}

.site-nav a:not(.button) {
  color: var(--ink-soft);
  font-size: 0.87rem;
  font-weight: 700;
  transition: color var(--transition);
}

.site-nav a:not(.button):hover {
  color: var(--copper);
}

.header-phone {
  color: var(--navy);
  font-size: 0.88rem;
  font-weight: 800;
  white-space: nowrap;
}

/* Buttons */
.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 11px;
  padding: 14px 24px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--copper);
  color: var(--white);
  cursor: pointer;
  font-size: 0.87rem;
  font-weight: 800;
  line-height: 1.3;
  text-align: center;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
  background: #a96338;
  color: var(--white);
}

.button-primary {
  background: var(--copper);
  color: var(--white);
}

.button-secondary {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--white);
}

.button-secondary:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--navy);
}

.button-dark {
  background: var(--navy);
  color: var(--white);
}

.button-dark:hover {
  background: var(--blue-hover);
}

.button-outline {
  border-color: var(--line);
  background: transparent;
  color: var(--navy);
}

.button-outline:hover {
  border-color: var(--navy);
  background: var(--navy);
  color: var(--white);
}

/* Hero */
.hero {
  position: relative;
  display: flex;
  min-height: 690px;
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background-color: var(--navy-deep);
  background-image:
    linear-gradient(
      90deg,
      rgba(16, 33, 44, 0.96) 0%,
      rgba(16, 33, 44, 0.86) 42%,
      rgba(16, 33, 44, 0.32) 100%
    ),
    url("https://joshbrooksconstructionllc.com/wp-content/uploads/2026/04/IMG_20251112_220214_251.webp?w=400&ssl=1");
  background-position: center, 72% center;
  background-size: cover;
}

.hero::after {
  position: absolute;
  z-index: -1;
  right: 0;
  bottom: 0;
  left: 0;
  height: 7px;
  background: var(--copper);
  content: "";
}

.hero-inner {
  position: relative;
  z-index: 1;
  width: min(var(--container), calc(100% - 64px));
  margin-inline: auto;
  padding-block: 100px 116px;
}

.hero-content {
  max-width: 700px;
}

.hero .eyebrow {
  color: var(--copper-light);
}

.hero h1 {
  max-width: 700px;
  margin-bottom: 24px;
  color: var(--white);
}

.hero h1 span {
  color: var(--copper-light);
}

.hero .lead {
  max-width: 590px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.86);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 42px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.84rem;
  font-weight: 600;
}

.hero-note::before {
  width: 34px;
  height: 2px;
  background: var(--copper);
  content: "";
}
```

