/* CSS PART 2 OF 3 */

/* Company credentials and positioning */
.trust-strip {
  padding-block: 27px;
  background: var(--navy);
  color: var(--white);
}

.trust-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 13px;
}

.trust-number {
  color: var(--copper-light);
  font-family: var(--font-heading);
  font-size: 1.8rem;
  font-weight: 900;
  line-height: 1;
}

.trust-label {
  max-width: 150px;
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1.4;
}

.trust-divider {
  width: 1px;
  height: 40px;
  background: rgba(255, 255, 255, 0.2);
}

/* Services */
.services-section {
  background: var(--paper);
}

.services-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 90px;
}

.services-intro {
  position: sticky;
  top: 35px;
}

.services-intro h2 {
  margin-bottom: 22px;
}

.services-intro p {
  margin-bottom: 28px;
}

.service-list {
  border-top: 1px solid var(--line);
}

.service-item {
  display: grid;
  grid-template-columns: 54px 1fr;
  gap: 22px;
  padding: 27px 0;
  border-bottom: 1px solid var(--line);
}

.service-index {
  color: var(--copper);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 900;
}

.service-item h3 {
  margin-bottom: 8px;
  font-size: 1.2rem;
}

.service-item p {
  max-width: 480px;
  margin-bottom: 0;
  font-size: 0.94rem;
}

/* How the work gets done */
.process-section {
  position: relative;
  overflow: hidden;
  background: var(--navy);
  color: var(--white);
}

.process-section .section-heading h2 {
  color: var(--white);
}

.process-section .section-heading p {
  color: rgba(255, 255, 255, 0.72);
}

.process-section .eyebrow {
  color: var(--copper-light);
}

.process-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.process-step {
  position: relative;
  padding: 36px 35px 24px 0;
}

.process-step + .process-step {
  padding-left: 35px;
  border-left: 1px solid rgba(255, 255, 255, 0.2);
}

.process-step-number {
  display: block;
  margin-bottom: 28px;
  color: var(--copper-light);
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 900;
  line-height: 1;
}

.process-step h3 {
  margin-bottom: 12px;
  color: var(--white);
}

.process-step p {
  max-width: 310px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.94rem;
}

/* Full-service contractor positioning */
.contractor-section {
  background: var(--surface);
}

.contractor-layout {
  display: grid;
  grid-template-columns: 1fr 0.9fr;
  align-items: center;
  gap: 85px;
}

.contractor-image {
  position: relative;
  min-height: 490px;
  overflow: hidden;
  background: var(--navy);
}

.contractor-image img {
  width: 100%;
  height: 490px;
  object-fit: cover;
}

.contractor-copy h2 {
  margin-bottom: 24px;
}

.contractor-copy > p {
  margin-bottom: 20px;
}

.contractor-points {
  display: grid;
  gap: 15px;
  margin-top: 28px;
}

.contractor-point {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  color: var(--navy);
  font-size: 0.94rem;
  font-weight: 700;
}

.contractor-point::before {
  display: flex;
  width: 23px;
  height: 23px;
  flex: 0 0 23px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--copper);
  color: var(--white);
  content: "✓";
  font-size: 0.75rem;
  font-weight: 900;
}

/* Roofing guidance */
.roof-section {
  background: var(--white);
}

.roof-layout {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  align-items: center;
  gap: 75px;
}

.roof-copy h2 {
  margin-bottom: 22px;
}

.roof-copy > p {
  margin-bottom: 28px;
}

.roof-checklist {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--line);
}

.roof-check-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding-block: 18px;
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  font-size: 0.94rem;
  font-weight: 650;
}

.roof-check-item::before {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  margin-top: 9px;
  border-radius: 50%;
  background: var(--copper);
  content: "";
}

.roof-image {
  position: relative;
  min-height: 540px;
  overflow: hidden;
  background: var(--surface);
}

.roof-image img {
  width: 100%;
  height: 540px;
  object-fit: cover;
  object-position: center;
}

.roof-image-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 23px 26px;
  background: rgba(16, 33, 44, 0.9);
  color: var(--white);
  font-size: 0.86rem;
  font-weight: 700;
}

/* Project portfolio */
.projects-section {
  background: var(--paper);
}

.projects-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 45px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.project-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  grid-template-rows: 280px 280px;
  gap: 22px;
}

.project-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--navy);
}

.project-card:first-child {
  grid-row: 1 / 3;
}

.project-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 450ms ease;
}

.project-card:hover img {
  transform: scale(1.035);
}

.project-card::after {
  position: absolute;
  inset: 35% 0 0;
  background: linear-gradient(
    0deg,
    rgba(16, 33, 44, 0.88),
    rgba(16, 33, 44, 0)
  );
  content: "";
  pointer-events: none;
}

.project-caption {
  position: absolute;
  z-index: 1;
  right: 25px;
  bottom: 23px;
  left: 25px;
  color: var(--white);
}

.project-caption span {
  display: block;
  margin-bottom: 5px;
  color: var(--copper-light);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.project-caption h3 {
  margin-bottom: 0;
  color: var(--white);
  font-size: 1.25rem;
}

/* Direct conversion bridge */
.estimate-band {
  padding-block: 65px;
  background: var(--copper);
}

.estimate-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
}

.estimate-inner h2 {
  max-width: 650px;
  margin-bottom: 8px;
  color: var(--white);
  font-size: clamp(1.8rem, 3vw, 2.7rem);
}

.estimate-inner p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.9);
}

.estimate-inner .button {
  flex-shrink: 0;
  border-color: var(--white);
  background: var(--white);
  color: var(--navy);
}

.estimate-inner .button:hover {
  background: var(--navy);
  color: var(--white);
}
```

