/* CSS PART 3 OF 3 */

/* Contact and conversion area */
.contact-section {
  padding-block: 108px;
  background: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 85px;
}

.contact-copy h2 {
  margin-bottom: 22px;
}

.contact-copy > p {
  margin-bottom: 32px;
}

.contact-details {
  display: grid;
  gap: 18px;
}

.contact-detail {
  display: flex;
  align-items: center;
  gap: 15px;
  color: var(--navy);
  font-weight: 750;
}

.contact-detail a {
  transition: color var(--transition);
}

.contact-detail a:hover {
  color: var(--copper);
}

.contact-icon {
  display: flex;
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  align-items: center;
  justify-content: center;
  background: var(--surface);
  color: var(--copper);
  font-size: 1.15rem;
}

.contact-form {
  padding: 40px;
  background: var(--paper);
  border: 1px solid var(--line);
}

.contact-form h3 {
  margin-bottom: 8px;
  font-size: 1.55rem;
}

.contact-form > p {
  margin-bottom: 28px;
  font-size: 0.91rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--navy);
  font-size: 0.82rem;
  font-weight: 800;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 50px;
  padding: 12px 14px;
  border: 1px solid #d5d6d1;
  border-radius: 2px;
  background: var(--white);
  color: var(--ink);
  outline-offset: 2px;
  transition: border-color var(--transition);
}

.form-field textarea {
  min-height: 130px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858e91;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--blue);
}

.contact-form .button {
  width: 100%;
  margin-top: 24px;
}

.form-note {
  margin: 14px 0 0;
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.6;
}

/* Footer */
.site-footer {
  padding-top: 55px;
  background: var(--navy-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 50px;
  padding-bottom: 48px;
}

.footer-brand {
  max-width: 390px;
}

.footer-brand .brand {
  margin-bottom: 20px;
  color: var(--white);
}

.footer-brand .brand-caption {
  color: rgba(255, 255, 255, 0.6);
}

.footer-brand p {
  color: rgba(255, 255, 255, 0.68);
  font-size: 0.9rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.85rem;
  font-weight: 700;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: var(--copper-light);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-block: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.58);
  font-size: 0.76rem;
}

/* Responsive navigation and layout */
@media (max-width: 1000px) {
  :root {
    --header-height: auto;
  }

  .header-inner {
    flex-wrap: wrap;
    padding-block: 15px;
    gap: 15px;
  }

  .site-nav {
    gap: 17px;
  }

  .services-layout,
  .contractor-layout,
  .roof-layout,
  .contact-layout {
    gap: 45px;
  }

  .services-layout {
    grid-template-columns: 0.8fr 1.2fr;
  }

  .trust-inner {
    flex-wrap: wrap;
    justify-content: center;
  }

  .trust-divider {
    display: none;
  }

  .project-grid {
    grid-template-rows: 240px 240px;
  }
}

@media (max-width: 720px) {
  .container,
  .hero-inner {
    width: min(100% - 40px, var(--container));
  }

  .section,
  .contact-section {
    padding-block: 72px;
  }

  .header-inner {
    align-items: center;
  }

  .brand img {
    width: 46px;
    height: 46px;
  }

  .brand-name {
    font-size: 0.88rem;
  }

  .brand-caption {
    font-size: 0.59rem;
  }

  .site-nav {
    width: 100%;
    justify-content: flex-start;
    overflow-x: auto;
    padding: 7px 0 4px;
    gap: 22px;
    scrollbar-width: thin;
  }

  .site-nav a:not(.button) {
    flex-shrink: 0;
    font-size: 0.8rem;
  }

  .site-nav .button {
    min-height: 42px;
    flex-shrink: 0;
    padding: 10px 15px;
    font-size: 0.78rem;
